{
  "findings": [
    {
      "check_id": "CKV_AWS_53",
      "title": "S3 public ACL blocking is not enabled",
      "resource": "aws_s3_bucket_public_access_block.document_storage",
      "severity": "CRITICAL",
      "explanation": "The public access block does not set block_public_acls to true, allowing new public ACLs to be applied to the S3 bucket or its objects."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket_public_access_block\" \"document_storage\" {\n  bucket                  = aws_s3_bucket.document_storage.id\n  block_public_acls       = true\n  block_public_policy     = true\n  ignore_public_acls      = true\n  restrict_public_buckets = true\n}\n",
  "fix_summary": "Enabled block_public_acls on the existing S3 public access block so that new public ACLs are rejected."
}
